INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_expense','admin','g_money','支出登錄','receipt','page','soon:支出登錄:本會帳戶直接付出去的錢（網銀轉帳廠商、自動扣繳、秘書薪資）在這裡登錄，寫進日記帳。志工或秘書長先墊的錢走「請款單」，不走這裡 —— 以「錢從誰口袋出」區分。',NULL,NULL,42,1);
INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_income','admin','g_money','收入登錄','coin','page','soon:收入登錄:官網來的訂單、報名、會費會自動入帳；贊助、補助、捐款在這裡手動登錄，寫進日記帳並登記收據編號。',NULL,NULL,43,1);
