INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_statement','admin','g_money','收支表','book','page','soon:收支表:依月／年彙總的收支，含預算執行率。目前在試算表用公式算，之後搬到這裡。',NULL,NULL,46,1);
INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_pl','admin','g_money','年度結餘表','book','page','soon:年度結餘表:本會是現金收支制，所以不做損益表，改做年度收支結餘。待預算表建好後一起做。',NULL,NULL,47,1);
INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_cash','admin','g_money','現金收支餘額表','book','page','soon:現金收支餘額表:取代資產負債表（現金收支制不適用）。列出各帳戶期初、收入、支出、期末。',NULL,NULL,48,1);
