INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_budget','admin','g_money','會計科目預算表','book','page','soon:會計科目預算表:年度預算（會員大會決議後由秘書長輸入），與實際支出對照顯示執行率，超支提醒。來源是「寓委聯115年度計畫甘特圖與預算表」。',NULL,NULL,50,1);
INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_forms','admin','g_money','空白表單','doc','page','soon:空白表單:支出證明單、講師費領據、印領清冊、補助金領據。之後會改成系統自動帶入資料後產生，不用手填。',NULL,NULL,51,1);
