INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_shared','admin','g_lib','經營管理資料','doc','page','soon:經營管理資料:會員共享資料夾裡的表單、公告範本、課程簡報。現在放在 Google 雲端硬碟，之後在這裡管理上下架與分類，官網會員專區直接讀。',NULL,NULL,56,1);
INSERT INTO meta_menu (id,area,parent_id,label,icon,kind,target,roles,badge,sort,visible) VALUES ('adm_community','admin','g_lib','社區資料','home','page','soon:社區資料:各社區的戶數、管理費、物業與廠商配合情形（來自「社區委員會聯誼交流群組分享資料」113 筆）。這份含各社區的敏感資訊，上線前要先決定誰看得到。',NULL,NULL,57,1);
